public class Profile
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid AccountId { get; set; }
    public string Name { get; set; }
    public List<Guid> Watchlist { get; } = new();
    public List<WatchProgress> WatchHistory { get; } = new();
}

public class OfflineDownload
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid ProfileId { get; set; }
    public Guid VideoId { get; set; }
    public string LocalPath { get; set; }
    public DateTime DownloadedAt { get; } = DateTime.UtcNow;
    public DateTime ExpiresAt { get; set; }
    public bool IsExpired => DateTime.UtcNow > ExpiresAt;
}

public class RecommendationService
{
    public IEnumerable<Video> GetPersonalized(Profile profile)
    {
        var history = profile.WatchHistory.Select(h => h.VideoId).ToHashSet();
        var preferredGenres = _watchHistory
            .Where(h => history.Contains(h.VideoId))
            .SelectMany(h => _videos[h.VideoId].Genres)
            .GroupBy(g => g)
            .OrderByDescending(g => g.Count())
            .Select(g => g.Key)
            .Take(3)
            .ToHashSet();

        return _videos
            .Where(v => preferredGenres.Overlaps(v.Genres) && !history.Contains(v.Id))
            .OrderByDescending(v => v.Rating)
            .Take(20);
    }
}
